// Gambar sampul tertanam langsung (tidak butuh folder img/). Ganti nilainya dengan "img/namafile.jpg" jika mau pakai gambar sendiri.
const SAMPUL = {
  1:"data:image/svg+xml;base64,",
  2:"data:image/svg+xml;base64,",
  3:"data:image/svg+xml;base64,",
  4:"data:image/svg+xml;base64,",
  5:"data:image/svg+xml;base64,",
  6:"data:image/svg+xml;base64,",
  7:"data:image/svg+xml;base64,",
  8:"data:image/svg+xml;base64,",
  9:"data:image/svg+xml;base64,",
  10:"data:image/svg+xml;base64,",
  11:"data:image/svg+xml;base64,",
  12:"data:image/svg+xml;base64,"
};

// Sampul buku: pakai gambar dari folder img/. Jika file tidak ada, tampil sampul gradasi.
// Untuk memakai gambar sendiri, ganti file di img/ (mis. buku-1.jpg) lalu ubah ekstensi di fungsi ini.
function sampulHTML(b){
  const bg = `linear-gradient(145deg,${b.warna[0]},${b.warna[1]})`;
  return `<div class="sampul" style="background:${bg}"><img src="${SAMPUL[b.id] || 'img/buku-' + b.id + '.svg'}" alt="Sampul buku ${b.judul}" data-judul="${b.judul}" loading="lazy" onerror="this.parentNode.innerHTML=IKON_BUKU+'<span>'+this.dataset.judul+'</span>'"></div>`;
}

// Membuat HTML satu kartu buku
function buatKartu(b){
  return `<article class="kartu">
    ${sampulHTML(b)}
    <div class="kartu-isi">
      <h3>${b.judul}</h3>
      <p class="penulis">${b.penulis}</p>
      <span class="badge">${b.kategori}</span>
      <button class="btn btn-kecil" data-id="${b.id}">Lihat Detail</button>
    </div></article>`;
}

// Menu mobile
const burger = document.getElementById("burger");
if (burger) burger.addEventListener("click", () => document.getElementById("menu").classList.toggle("buka"));

// ===== Halaman Home: buku populer =====
const populer = document.getElementById("populer");
if (populer) {
  populer.innerHTML = BUKU.filter(b => b.populer).map(buatKartu).join("");
  populer.addEventListener("click", e => {
    const t = e.target.closest("button[data-id]");
    if (t) location.href = "koleksi.html?buku=" + t.dataset.id;
  });
}
const formHome = document.getElementById("formCariHome");
if (formHome) formHome.addEventListener("submit", e => {
  e.preventDefault();
  location.href = "koleksi.html?q=" + encodeURIComponent(document.getElementById("cariHome").value.trim());
});

// ===== Halaman Koleksi: cari + filter + detail =====
const daftar = document.getElementById("daftarBuku");
if (daftar) {
  const input = document.getElementById("cari");
  const kosong = document.getElementById("kosong");
  const modal = document.getElementById("modal");
  const chips = document.querySelectorAll(".chip");
  let kategoriAktif = "Semua";

  function tampilkan() {
    const kata = input.value.toLowerCase().trim();
    const hasil = BUKU.filter(b =>
      (kategoriAktif === "Semua" || b.kategori === kategoriAktif) &&
      (b.judul + " " + b.penulis + " " + b.kategori).toLowerCase().includes(kata));
    daftar.innerHTML = hasil.map(buatKartu).join("");
    kosong.style.display = hasil.length ? "none" : "block";
  }

  function setKategori(k) {
    kategoriAktif = k;
    chips.forEach(c => c.classList.toggle("aktif", c.dataset.kat === k));
    tampilkan();
  }

  function bukaDetail(id) {
    const b = BUKU.find(x => x.id === Number(id));
    if (!b) return;
    document.getElementById("mSampul").innerHTML = sampulHTML(b);
    document.getElementById("mJudul").textContent = b.judul;
    document.getElementById("mSinopsis").textContent = b.sinopsis;
    document.getElementById("mInfo").innerHTML =
      `<dt>Penulis</dt><dd>${b.penulis}</dd><dt>Kategori</dt><dd>${b.kategori}</dd><dt>Tahun</dt><dd>${b.tahun}</dd><dt>Halaman</dt><dd>${b.halaman}</dd>`;
    modal.classList.add("buka");
  }

  input.addEventListener("input", tampilkan);
  document.getElementById("formCari").addEventListener("submit", e => { e.preventDefault(); tampilkan(); });
  chips.forEach(c => c.addEventListener("click", () => setKategori(c.dataset.kat)));
  daftar.addEventListener("click", e => {
    const t = e.target.closest("button[data-id]");
    if (t) bukaDetail(t.dataset.id);
  });
  document.getElementById("tutup").addEventListener("click", () => modal.classList.remove("buka"));
  modal.addEventListener("click", e => { if (e.target === modal) modal.classList.remove("buka"); });
  document.addEventListener("keydown", e => { if (e.key === "Escape") modal.classList.remove("buka"); });

  // Baca parameter dari halaman Home (?q=, ?kategori=, ?buku=)
  const p = new URLSearchParams(location.search);
  if (p.get("q")) input.value = p.get("q");
  setKategori(p.get("kategori") || "Semua");
  if (p.get("buku")) bukaDetail(p.get("buku"));
}